        if isinstance(v, dict):
            x = v.get("x", v.get("col", v.get("cx", v.get("i"))))
            y = v.get("y", v.get("row", v.get("cy", v.get("j"))))
            if isinstance(x, int) and isinstance(y, int):
                return [x, y]
        if isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], int) and isinstance(v[1], int):
            return [v[0], v[1]]
        return None

    def gather(v, out):
        p = pos(v)
        if p is not None:
            out.append(p)
        elif isinstance(v, dict):
            for x in v.values():
                if isinstance(x, (dict, list, tuple)):
                    gather(x, out)
        elif isinstance(v, (list, tuple)):
            for x in v:
                if isinstance(x, (dict, list, tuple)):
                    gather(x, out)

    me = pos(observation.get("self_position")) or pos(observation.get("position")) or [0, 0]
    op = pos(observation.get("opponent_position")) or [me[0], me[1]]
    resources, obstacles = [], []
    gather(observation.get("resources"), resources)
    gather(observation.get("obstacles"), obstacles)
