        return 0 <= x < w and 0 <= y < h and (x, y) not in occ

    def score(dx, dy):
        x, y = me[0] + dx, me[1] + dy
        if not good(x, y):
            return -10**9
        s = 0
        if resources:
            d = min(abs(x - r[0]) + abs(y - r[1]) for r in resources)
